<script lang="ts">import type{PageData}from'./$types';export let data:PageData;</script><div class="hii-page grid gap-8 lg:grid-cols-[240px_minmax(0,1fr)]"><aside class="hii-side-nav"><a href="/feed" class="hii-side-link" data-active="true">Offline feed</a><a href="/dashboard" class="hii-side-link">Dashboard</a><a href="/console" class="hii-side-link">Console</a><a href="/upload" class="hii-side-link">Exchange</a><div class="hii-card text-xs">{data.posts.length} links · {data.posts.filter((p:any)=>p.cache?.status==='cached').length} cached</div></aside><div><p class="hii-kicker">hii browser loop</p><h1 class="hii-page-title">Stream links. Keep local proof.</h1><p class="hii-page-copy text-sm">The browser captures useful pages, the downloader caches them locally, and Ollama creates offline summaries.</p><form method="POST" class="hii-card mt-8 grid gap-3 lg:grid-cols-[1fr_1fr_auto]"><input name="url" required placeholder="https://example.com" class="hii-field px-3 py-2"/><input name="title" required placeholder="Why this matters" class="hii-field px-3 py-2"/><button class="hii-command-button">Save</button><input name="note" placeholder="Optional context" class="hii-field px-3 py-2"/><input name="tags" placeholder="hii, browser, local" class="hii-field px-3 py-2"/><input name="source" type="hidden" value="manual"/></form><div class="mt-8 grid gap-4">{#each data.posts as post}<article class="hii-card"><div class="flex justify-between"><div><span class="font-mono text-xs uppercase text-neutral-500">{post.source}</span><h2 class="mt-2 text-xl font-semibold">{post.title}</h2><a href={post.url} class="hii-resource-link font-mono text-xs">{post.url}</a></div><time class="font-mono text-xs text-neutral-500">{new Date(post.createdAt).toLocaleString()}</time></div>{#if post.note}<p class="mt-3 text-sm">{post.note}</p>{/if}{#if post.cache?.summary}<div class="mt-4 border-l-2 border-[var(--hii-electric-blue)] pl-3 text-sm">{post.cache.summary}</div>{/if}</article>{/each}</div></div></div>
